/*Table structure for table `forensic` */

DROP TABLE IF EXISTS `forensic`;

CREATE TABLE `forensic` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(1000) DEFAULT NULL,
  `email` varchar(1000) DEFAULT NULL,
  `username` varchar(1000) DEFAULT NULL,
  `password` varchar(1000) DEFAULT NULL,
  `status` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=latin1;

/*Data for the table `forensic` */

insert  into `forensic`(`id`,`name`,`email`,`username`,`password`,`status`) values (1,'kishan','xyz@gmail.com','kishan','123','Authorized');

/*Table structure for table `police` */

DROP TABLE IF EXISTS `police`;

CREATE TABLE `police` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `station` varchar(1000) DEFAULT NULL,
  `police` varchar(1000) DEFAULT NULL,
  `email` varchar(1000) DEFAULT NULL,
  `p_id` varchar(1000) DEFAULT NULL,
  `password` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=latin1;

/*Data for the table `police` */

insert  into `police`(`id`,`station`,`police`,`email`,`p_id`,`password`) values (3,'ECIL','Kishan','abc@gmail.com','968154','SGwOKd');

